Lemma bc_A2 : forall (fr : bvmap 5 word) cs regs (m : word -> option byte) (s pixs : Z),
  frm_zero cs ->
  (4096 + 272 <= s <= 2 ^ 47)%Z ->
  (0 <= pixs < 2 ^ 64)%Z ->
  store_ok SEGS m (Z_to_bv 64 (s - 272)) 272 = true ->
  getr regs 2 = Z_to_bv 64 (s - 272) ->
  getr regs 10 = Z_to_bv 64 pixs ->
  reg_get fr 15 = Z_to_bv 64 18446744070479937536 ->
  reg_get fr 9 = Z_to_bv 64 18446744070498811904 ->
  reach SEGS (@mkst (mkFP fr cs) regs (Z_to_bv 64 186568) m rom)
    (fun fin => exists fr' cs' regs' M', fin = @mkst (mkFP fr' cs') regs' (Z_to_bv 64 112404) M' rom /\ frm_zero cs' /\
      rinv [((s - 184)%Z, 8%Z)] m M' /\ rdn SEGS M' (Z_to_bv 64 (s - 184)) 8 = Some (Z_to_le_bytes 8 11) /\
      getr regs' 1 = Z_to_bv 64 186616 /\ getr regs' 2 = Z_to_bv 64 (s - 272) /\ getr regs' 10 = Z_to_bv 64 pixs /\ getr regs' 11 = Z_to_bv 64 11 /\
      getr regs' 12 = Z_to_bv 64 11 /\ getr regs' 13 = Z_to_bv 64 11 /\ getr regs' 14 = Z_to_bv 64 11 /\
      regs_agree (fun r => In r [1; 11; 12; 13; 14]%list) regs regs' /\
      reg_get fr' 9 = Z_to_bv 64 18446744070498811904 /\ (forall r : reg, ~ In (ridx r) [9; 14; 15]%nat -> reg_get fr' r = reg_get fr r)).
Proof.
