Lemma bc_C : forall (fx : FPState) regs (m : word -> option byte) (s pixs bsc : Z),
  (4096 + 272 <= s <= 2 ^ 47)%Z ->
  (0 <= pixs < 2 ^ 64)%Z ->
  rdn SEGS m (Z_to_bv 64 (s - 160)) 8 = Some (Z_to_le_bytes 8 pixs) ->
  getr regs 2 = Z_to_bv 64 (s - 272) ->
  reach SEGS (@mkst fx regs (Z_to_bv 64 186656) m rom)
    (fun fin => exists regs' M', fin = @mkst fx regs' (Z_to_bv 64 121072) M' rom /\
      M' = m /\ getr regs' 1 = Z_to_bv 64 186692 /\ getr regs' 2 = Z_to_bv 64 (s - 272) /\ getr regs' 10 = Z_to_bv 64 pixs /\ getr regs' 11 = Z_to_bv 64 1 /\
      getr regs' 12 = Z_to_bv 64 5 /\ getr regs' 13 = Z_to_bv 64 0 /\ getr regs' 14 = Z_to_bv 64 0 /\ getr regs' 15 = Z_to_bv 64 0 /\
      getr regs' 16 = Z_to_bv 64 (s - 152) /\ getr regs' 8 = Z_to_bv 64 5 /\
      regs_agree (fun r => In r [1; 8; 10; 11; 12; 13; 14; 15; 16]%list) regs regs').
Proof.
