Lemma bc_Dn : forall (fx : FPState) regs (m : word -> option byte) (s pixs : Z),
  (4096 + 272 + 32 <= s <= 2 ^ 47)%Z ->
  (4096 <= pixs)%Z ->
  (pixs + 64 <= s - 304)%Z ->
  (pixs mod 16 = 0)%Z ->
  (438272 <= s - 304)%Z ->
  (pixs + 64 <= 65536 \/ 438272 <= pixs)%Z ->
  rdn SEGS m (Z_to_bv 64 (s - 160)) 8 = Some (Z_to_le_bytes 8 pixs) ->
  rdn SEGS m (Z_to_bv 64 (pixs + 20)) 4 = Some (Z_to_le_bytes 4 2) ->
  (forall j, (230424 <= j < 230584)%Z -> m (Z_to_bv 64 j) = None) ->
  (forall j, (234720 <= j < 234728)%Z -> m (Z_to_bv 64 j) = None) ->
  store_ok SEGS m (Z_to_bv 64 (s - 304)) 304 = true ->
  store_ok SEGS m (Z_to_bv 64 (pixs + 20)) 4 = true ->
  getr regs 2 = Z_to_bv 64 (s - 272) ->
  getr regs 9 = Z_to_bv 64 0 ->
  getr regs 8 = Z_to_bv 64 5 ->
  reach SEGS (@mkst fx regs (Z_to_bv 64 186692) m rom)
    (fun fin => exists regs' M', fin = @mkst fx regs' (Z_to_bv 64 97396) M' rom /\
      rinv [((s - 304)%Z, 32%Z); ((s - 160)%Z, 8%Z); ((pixs + 20)%Z, 4%Z)] m M' /\
      rdn SEGS M' (Z_to_bv 64 (pixs + 20)) 4 = Some (Z_to_le_bytes 4 1) /\
      getr regs' 1 = Z_to_bv 64 188388 /\ getr regs' 2 = Z_to_bv 64 (s - 272) /\ getr regs' 10 = Z_to_bv 64 75018 /\ getr regs' 11 = Z_to_bv 64 68121 /\
      getr regs' 12 = Z_to_bv 64 0 /\
      regs_agree (fun r => In r [1; 5; 6; 7; 10; 11; 12; 13; 14; 15; 16; 17; 28; 29; 30; 31]%list) regs regs').
