Lemma bc_E : forall (fr : bvmap 5 word) cs regs (m : word -> option byte) (s pixs bsc bil minv maxv : Z),
  frm_zero cs ->
  (4096 + 272 <= s <= 2 ^ 47)%Z ->
  (4096 <= pixs)%Z ->
  (pixs + 64 <= s - 272)%Z ->
  (pixs mod 16 = 0)%Z ->
  (0 <= bsc < 2 ^ 64)%Z ->
  (4096 <= bil)%Z ->
  (bil + 104 <= s - 272)%Z ->
  (bil + 104 <= pixs \/ pixs + 64 <= bil)%Z ->
  (0 <= minv <= 255)%Z ->
  (0 <= maxv <= 255)%Z ->
  rdn SEGS m (Z_to_bv 64 (s - 148)) 4 = Some (Z_to_le_bytes 4 minv) ->
  rdn SEGS m (Z_to_bv 64 (s - 152)) 4 = Some (Z_to_le_bytes 4 maxv) ->
  rdn SEGS m (Z_to_bv 64 (s - 216)) 8 = Some (Z_to_le_bytes 8 10) ->
  rdn SEGS m (Z_to_bv 64 (pixs + 20)) 4 = Some (Z_to_le_bytes 4 1) ->
  store_ok SEGS m (Z_to_bv 64 bil) 104 = true ->
  store_ok SEGS m (Z_to_bv 64 (pixs + 20)) 4 = true ->
  getr regs 2 = Z_to_bv 64 (s - 272) ->
  getr regs 10 = Z_to_bv 64 bil ->
  getr regs 9 = Z_to_bv 64 bsc ->
  getr regs 21 = Z_to_bv 64 1 ->
  getr regs 22 = Z_to_bv 64 pixs ->
  reach SEGS (@mkst (mkFP fr cs) regs (Z_to_bv 64 186716) m rom)
    (fun fin => exists fr' cs' regs' M', fin = @mkst (mkFP fr' cs') regs' (Z_to_bv 64 194260) M' rom /\ frm_zero cs' /\
      rinv [(bil, 104%Z); ((pixs + 20)%Z, 4%Z)] m M' /\
      rdn SEGS M' (Z_to_bv 64 bil) 8 = Some (Z_to_le_bytes 8 pixs) /\ rdn SEGS M' (Z_to_bv 64 (bil + 8)) 8 = Some (Z_to_le_bytes 8 bsc) /\
      rdn SEGS M' (Z_to_bv 64 (bil + 16)) 4 = Some (Z_to_le_bytes 4 1) /\ rdn SEGS M' (Z_to_bv 64 (bil + 48)) 4 = Some (Z_to_le_bytes 4 minv) /\
      rdn SEGS M' (Z_to_bv 64 (bil + 52)) 4 = Some (Z_to_le_bytes 4 maxv) /\ rdn SEGS M' (Z_to_bv 64 (bil + 56)) 4 = Some (Z_to_le_bytes 4 10) /\
      rdn SEGS M' (Z_to_bv 64 (pixs + 20)) 4 = Some (Z_to_le_bytes 4 2) /\
      getr regs' 1 = Z_to_bv 64 186788 /\ getr regs' 2 = Z_to_bv 64 (s - 272) /\ getr regs' 10 = Z_to_bv 64 10 /\ getr regs' 11 = Z_to_bv 64 4 /\
      getr regs' 20 = Z_to_bv 64 bil /\ getr regs' 19 = Z_to_bv 64 bsc /\ getr regs' 9 = Z_to_bv 64 10 /\
      regs_agree (fun r => In r [1; 9; 10; 11; 12; 19; 20]%list) regs regs' /\
      (forall r : reg, ~ In (ridx r) (@nil nat) -> reg_get fr' r = reg_get fr r)).
