Lemma bc_G2 : forall (fx : FPState) regs (m : word -> option byte) (s bil kx : Z),
  (4096 + 272 <= s <= 2 ^ 47)%Z ->
  (4096 <= bil)%Z ->
  (bil + 104 <= s - 272)%Z ->
  (0 <= kx < 2 ^ 64)%Z ->
  store_ok SEGS m (Z_to_bv 64 bil) 104 = true ->
  getr regs 2 = Z_to_bv 64 (s - 272) ->
  getr regs 20 = Z_to_bv 64 bil ->
  getr regs 10 = Z_to_bv 64 kx ->
  reach SEGS (@mkst fx regs (Z_to_bv 64 186984) m rom)
    (fun fin => exists regs' M', fin = @mkst fx regs' (Z_to_bv 64 194260) M' rom /\
      rinv [((bil + 72)%Z, 8%Z)] m M' /\ rdn SEGS M' (Z_to_bv 64 (bil + 72)) 8 = Some (Z_to_le_bytes 8 kx) /\
      getr regs' 1 = Z_to_bv 64 187000 /\ getr regs' 2 = Z_to_bv 64 (s - 272) /\ getr regs' 10 = Z_to_bv 64 256 /\ getr regs' 11 = Z_to_bv 64 4 /\
