Lemma bc_H2 : forall (fx : FPState) regs (m : word -> option byte) (s bil kf : Z),
  (4096 + 272 <= s <= 2 ^ 47)%Z ->
  (4096 <= bil)%Z ->
  (bil + 104 <= s - 272)%Z ->
  (0 <= kf < 2 ^ 64)%Z ->
  store_ok SEGS m (Z_to_bv 64 bil) 104 = true ->
  getr regs 2 = Z_to_bv 64 (s - 272) ->
  getr regs 20 = Z_to_bv 64 bil ->
  getr regs 10 = Z_to_bv 64 kf ->
  getr regs 17 = Z_to_bv 64 11 ->
  reach SEGS (@mkst fx regs (Z_to_bv 64 187132) m rom)
    (fun fin => exists regs' M', fin = @mkst fx regs' (Z_to_bv 64 194260) M' rom /\
      rinv [((bil + 80)%Z, 8%Z)] m M' /\ rdn SEGS M' (Z_to_bv 64 (bil + 80)) 8 = Some (Z_to_le_bytes 8 kf) /\
      getr regs' 1 = Z_to_bv 64 187152 /\ getr regs' 2 = Z_to_bv 64 (s - 272) /\ getr regs' 10 = Z_to_bv 64 11 /\ getr regs' 11 = Z_to_bv 64 4 /\ getr regs' 18 = Z_to_bv 64 11 /\
      regs_agree (fun r => In r [1; 10; 11; 18]%list) regs regs').
Proof.
