Lemma bc_J : forall (fx : FPState) regs (m : word -> option byte) (s bil spat : Z),
  (4096 + 272 <= s <= 2 ^ 47)%Z ->
  (4096 <= bil)%Z ->
  (bil + 104 <= s - 272)%Z ->
  (0 <= spat < 2 ^ 64)%Z ->
  store_ok SEGS m (Z_to_bv 64 bil) 104 = true ->
  getr regs 2 = Z_to_bv 64 (s - 272) ->
  getr regs 20 = Z_to_bv 64 bil ->
  getr regs 23 = Z_to_bv 64 spat ->
  reach SEGS (@mkst fx regs (Z_to_bv 64 187220) m rom)
    (fun fin => exists regs' M', fin = @mkst fx regs' (Z_to_bv 64 194260) M' rom /\
      rinv [((bil + 32)%Z, 8%Z)] m M' /\ rdn SEGS M' (Z_to_bv 64 (bil + 32)) 8 = Some (Z_to_le_bytes 8 spat) /\
      getr regs' 1 = Z_to_bv 64 187240 /\ getr regs' 2 = Z_to_bv 64 (s - 272) /\ getr regs' 10 = Z_to_bv 64 256 /\ getr regs' 11 = Z_to_bv 64 4 /\ getr regs' 8 = Z_to_bv 64 256 /\
      regs_agree (fun r => In r [1; 8; 10; 11]%list) regs regs').
Proof.
