Lemma bc_I : forall (fr : bvmap 5 word) cs regs (m : word -> option byte) (s arr : Z),
  frm_zero cs ->
  (4096 + 272 <= s <= 2 ^ 47)%Z ->
  (0 <= arr < 2 ^ 64)%Z ->
  getr regs 2 = Z_to_bv 64 (s - 272) ->
  getr regs 10 = Z_to_bv 64 arr ->
  getr regs 18 = Z_to_bv 64 11 ->
  reg_get fr 9 = Z_to_bv 64 18446744070498811904 ->
  reach SEGS (@mkst (mkFP fr cs) regs (Z_to_bv 64 187152) m rom)
    (fun fin => exists fr' cs' regs' M', fin = @mkst (mkFP fr' cs') regs' (Z_to_bv 64 187184) M' rom /\ frm_zero cs' /\
      M' = m /\ getr regs' 23 = Z_to_bv 64 arr /\ getr regs' 8 = Z_to_bv 64 0 /\ getr regs' 9 = Z_to_bv 64 arr /\
      regs_agree (fun r => In r [8; 9; 23]%list) regs regs' /\
      reg_get fr' 9 = Z_to_bv 64 4621819117588971520 /\ reg_get fr' 18 = Z_to_bv 64 18446744070526599168 /\ (forall r : reg, ~ In (ridx r) [9; 15; 18]%nat -> reg_get fr' r = reg_get fr r)).
Proof.
