Lemma bc_K : forall (fr : bvmap 5 word) cs regs (m : word -> option byte) (s arr : Z),
  frm_zero cs ->
  (4096 + 272 <= s <= 2 ^ 47)%Z ->
  (0 <= arr < 2 ^ 64)%Z ->
  getr regs 2 = Z_to_bv 64 (s - 272) ->
  getr regs 10 = Z_to_bv 64 arr ->
  reg_get fr 8 = Z_to_bv 64 18446744070507200512 ->
  reach SEGS (@mkst (mkFP fr cs) regs (Z_to_bv 64 187240) m rom)
    (fun fin => exists fr' cs' regs' M', fin = @mkst (mkFP fr' cs') regs' (Z_to_bv 64 187268) M' rom /\ frm_zero cs' /\
      M' = m /\ getr regs' 24 = Z_to_bv 64 arr /\ getr regs' 9 = Z_to_bv 64 0 /\ getr regs' 18 = Z_to_bv 64 arr /\
      regs_agree (fun r => In r [9; 18; 24]%list) regs regs' /\
      reg_get fr' 8 = Z_to_bv 64 18446744070543376384 /\ (forall r : reg, ~ In (ridx r) [8; 14; 15]%nat -> reg_get fr' r = reg_get fr r)).
