Lemma bc_L : forall (fx : FPState) regs (m : word -> option byte) (s bil rng : Z),
  (4096 + 272 <= s <= 2 ^ 47)%Z ->
  (4096 <= bil)%Z ->
  (bil + 104 <= s - 272)%Z ->
  (0 <= rng < 2 ^ 64)%Z ->
  rdn SEGS m (Z_to_bv 64 (s - 216)) 8 = Some (Z_to_le_bytes 8 10) ->
  store_ok SEGS m (Z_to_bv 64 bil) 104 = true ->
  store_ok SEGS m (Z_to_bv 64 (s - 272)) 272 = true ->
  getr regs 2 = Z_to_bv 64 (s - 272) ->
  getr regs 20 = Z_to_bv 64 bil ->
  getr regs 24 = Z_to_bv 64 rng ->
  reach SEGS (@mkst fx regs (Z_to_bv 64 187304) m rom)
    (fun fin => exists regs' M', fin = @mkst fx regs' (Z_to_bv 64 98280) M' rom /\
      rinv [((s - 272)%Z, 8%Z); ((bil + 40)%Z, 8%Z)] m M' /\ rdn SEGS M' (Z_to_bv 64 (s - 272)) 8 = Some (Z_to_le_bytes 8 bil) /\
      rdn SEGS M' (Z_to_bv 64 (bil + 40)) 8 = Some (Z_to_le_bytes 8 rng) /\
      getr regs' 1 = Z_to_bv 64 187320 /\ getr regs' 2 = Z_to_bv 64 (s - 272) /\ getr regs' 10 = Z_to_bv 64 10 /\
      regs_agree (fun r => In r [1; 10]%list) regs regs').
Proof.
