Lemma bc_M : forall (fr : bvmap 5 word) cs regs (m : word -> option byte) (s pa bsc pixs nc ws hs wpls datas w h : Z),
  frm_zero cs ->
  (4096 + 272 <= s <= 2 ^ 47)%Z ->
  (0 <= pa < 2 ^ 64)%Z ->
  (4096 <= bsc)%Z ->
  (bsc + 64 <= s - 272)%Z ->
  (4096 <= pixs)%Z ->
  (pixs + 64 <= s - 272)%Z ->
  (0 <= nc < 2 ^ 64)%Z ->
  (0 <= ws < 2 ^ 31)%Z ->
  (0 <= hs < 2 ^ 31)%Z ->
  (0 <= wpls <= 20000)%Z ->
  (0 <= datas < 2 ^ 47)%Z ->
  (0 <= w < 2 ^ 31)%Z ->
  (0 <= h < 2 ^ 31)%Z ->
  rdn SEGS m (Z_to_bv 64 bsc) 4 = Some (Z_to_le_bytes 4 ws) ->
  rdn SEGS m (Z_to_bv 64 (bsc + 4)) 4 = Some (Z_to_le_bytes 4 hs) ->
  rdn SEGS m (Z_to_bv 64 (bsc + 16)) 4 = Some (Z_to_le_bytes 4 wpls) ->
  rdn SEGS m (Z_to_bv 64 (bsc + 56)) 8 = Some (Z_to_le_bytes 8 datas) ->
  rdn SEGS m (Z_to_bv 64 pixs) 4 = Some (Z_to_le_bytes 4 w) ->
  rdn SEGS m (Z_to_bv 64 (pixs + 4)) 4 = Some (Z_to_le_bytes 4 h) ->
  rdn SEGS m (Z_to_bv 64 (s - 184)) 8 = Some (Z_to_le_bytes 8 11) ->
  store_ok SEGS m (Z_to_bv 64 (s - 272)) 272 = true ->
  getr regs 2 = Z_to_bv 64 (s - 272) ->
  getr regs 10 = Z_to_bv 64 pa ->
  getr regs 19 = Z_to_bv 64 bsc ->
  getr regs 22 = Z_to_bv 64 pixs ->
  getr regs 21 = Z_to_bv 64 1 ->
  getr regs 26 = Z_to_bv 64 nc ->
  reg_get fr 9 = Z_to_bv 64 4621819117588971520 ->
  reach SEGS (@mkst (mkFP fr cs) regs (Z_to_bv 64 187320) m rom)
    (fun fin => exists fr' cs' regs' M', fin = @mkst (mkFP fr' cs') regs' (Z_to_bv 64 187564) M' rom /\ frm_zero cs' /\
      rinv [((s - 264)%Z, 48%Z); ((s - 144)%Z, 16%Z)] m M' /\
      rdn SEGS M' (Z_to_bv 64 (s - 224)) 8 = Some (Z_to_le_bytes 8 pa) /\ rdn SEGS M' (Z_to_bv 64 (s - 232)) 8 = Some (Z_to_le_bytes 8 bsc) /\
      rdn SEGS M' (Z_to_bv 64 (s - 240)) 8 = Some (Z_to_le_bytes 8 nc) /\
      rdn SEGS M' (Z_to_bv 64 (s - 248)) 8 = Some (Z_to_le_bytes 8 (datas + 11 * (4 * wpls) + 22)) /\
      rdn SEGS M' (Z_to_bv 64 (s - 256)) 8 = Some (Z_to_le_bytes 8 (datas + 11 * (4 * wpls) + 1)) /\
      rdn SEGS M' (Z_to_bv 64 (s - 264)) 8 = Some (Z_to_le_bytes 8 (2 ^ 64 - 40)) /\
      getr regs' 2 = Z_to_bv 64 (s - 272) /\ getr regs' 8 = Z_to_bv 64 0 /\ getr regs' 9 = Z_to_bv 64 bsc /\ getr regs' 11 = Z_to_bv 64 bsc /\
      getr regs' 18 = Z_to_bv 64 (2 ^ 64 - 10) /\ getr regs' 19 = Z_to_bv 64 (4 * wpls) /\ getr regs' 20 = Z_to_bv 64 21 /\
      getr regs' 21 = Z_to_bv 64 h /\ getr regs' 22 = Z_to_bv 64 w /\ getr regs' 25 = Z_to_bv 64 10 /\
      regs_agree (fun r => In r [1; 8; 9; 10; 11; 12; 13; 14; 18; 19; 20; 21; 22; 25]%list) regs regs' /\
