Lemma bc_N : forall (fx : FPState) regs (m : word -> option byte) (s bsc : Z),
  (4096 + 272 <= s <= 2 ^ 47)%Z ->
  (0 <= bsc < 2 ^ 64)%Z ->
  getr regs 2 = Z_to_bv 64 (s - 272) ->
  getr regs 11 = Z_to_bv 64 bsc ->
  reach SEGS (@mkst fx regs (Z_to_bv 64 187564) m rom)
    (fun fin => exists regs' M', fin = @mkst fx regs' (Z_to_bv 64 105628) M' rom /\
      M' = m /\ getr regs' 1 = Z_to_bv 64 187572 /\ getr regs' 2 = Z_to_bv 64 (s - 272) /\ getr regs' 10 = Z_to_bv 64 0 /\ getr regs' 11 = Z_to_bv 64 bsc /\
      regs_agree (fun r => In r [1; 10]%list) regs regs').
