Lemma bc_O : forall (fx : FPState) regs (m : word -> option byte) (s pixt nc idx datat wplt kval hd t6v a2v : Z),
  (4096 + 272 <= s <= 2 ^ 47)%Z ->
  (4096 <= pixt)%Z ->
  (pixt + 64 <= s - 272)%Z ->
  (4096 <= nc)%Z ->
  (nc + 40 <= s - 272)%Z ->
  (0 <= idx < 10)%Z ->
  (0 <= datat < 2 ^ 47)%Z ->
  (0 <= wplt <= 20000)%Z ->
  (0 <= kval <= 255)%Z ->
  (1 <= hd < 2 ^ 31)%Z ->
  (0 <= t6v < 2 ^ 64)%Z ->
  (0 <= a2v < 2 ^ 64)%Z ->
  rdn SEGS m (Z_to_bv 64 (pixt + 56)) 8 = Some (Z_to_le_bytes 8 datat) ->
  rdn SEGS m (Z_to_bv 64 (pixt + 16)) 4 = Some (Z_to_le_bytes 4 wplt) ->
  rdn SEGS m (Z_to_bv 64 (nc + 4 * idx)) 4 = Some (Z_to_le_bytes 4 kval) ->
  rdn SEGS m (Z_to_bv 64 (s - 184)) 8 = Some (Z_to_le_bytes 8 11) ->
  rdn SEGS m (Z_to_bv 64 (s - 248)) 8 = Some (Z_to_le_bytes 8 t6v) ->
  rdn SEGS m (Z_to_bv 64 (s - 256)) 8 = Some (Z_to_le_bytes 8 a2v) ->
  store_ok SEGS m (Z_to_bv 64 (s - 272)) 272 = true ->
  getr regs 2 = Z_to_bv 64 (s - 272) ->
  getr regs 10 = Z_to_bv 64 pixt ->
  getr regs 8 = Z_to_bv 64 idx ->
  getr regs 26 = Z_to_bv 64 nc ->
  getr regs 21 = Z_to_bv 64 hd ->
  reach SEGS (@mkst fx regs (Z_to_bv 64 187572) m rom)
    (fun fin => exists regs' M', fin = @mkst fx regs' (Z_to_bv 64 187660) M' rom /\
      rinv [((s - 176)%Z, 8%Z)] m M' /\ rdn SEGS M' (Z_to_bv 64 (s - 176)) 8 = Some (Z_to_le_bytes 8 pixt) /\
      getr regs' 1 = Z_to_bv 64 datat /\ getr regs' 2 = Z_to_bv 64 (s - 272) /\ getr regs' 9 = Z_to_bv 64 77024 /\ getr regs' 10 = Z_to_bv 64 0 /\
      getr regs' 11 = Z_to_bv 64 (datat + 11) /\ getr regs' 12 = Z_to_bv 64 a2v /\ getr regs' 26 = Z_to_bv 64 kval /\ getr regs' 27 = Z_to_bv 64 wplt /\
      getr regs' 30 = Z_to_bv 64 11 /\ getr regs' 31 = Z_to_bv 64 t6v /\
      regs_agree (fun r => In r [1; 9; 10; 11; 12; 26; 27; 30; 31]%list) regs regs').
