Lemma bc_P : forall (fx : FPState) regs (m : word -> option byte) (s idx datat wd hd : Z),
  (4096 + 272 <= s <= 2 ^ 47)%Z ->
  (0 <= idx < 2 ^ 64)%Z ->
  (0 <= datat < 2 ^ 64)%Z ->
  (0 <= wd < 2 ^ 64)%Z ->
  (0 <= hd < 2 ^ 64)%Z ->
  store_ok SEGS m (Z_to_bv 64 (s - 272)) 272 = true ->
  getr regs 2 = Z_to_bv 64 (s - 272) ->
  getr regs 8 = Z_to_bv 64 idx ->
  getr regs 1 = Z_to_bv 64 datat ->
  getr regs 22 = Z_to_bv 64 wd ->
  getr regs 21 = Z_to_bv 64 hd ->
  reach SEGS (@mkst fx regs (Z_to_bv 64 187872) m rom)
    (fun fin => exists regs' M', fin = @mkst fx regs' (Z_to_bv 64 102180) M' rom /\
      rinv [((s - 200)%Z, 16%Z)] m M' /\ rdn SEGS M' (Z_to_bv 64 (s - 192)) 8 = Some (Z_to_le_bytes 8 idx) /\
      rdn SEGS M' (Z_to_bv 64 (s - 200)) 8 = Some (Z_to_le_bytes 8 datat) /\
      getr regs' 1 = Z_to_bv 64 187896 /\ getr regs' 2 = Z_to_bv 64 (s - 272) /\ getr regs' 10 = Z_to_bv 64 wd /\ getr regs' 11 = Z_to_bv 64 hd /\
      getr regs' 12 = Z_to_bv 64 8 /\ regs_agree (fun r => In r [1; 10; 11; 12]%list) regs regs').
