Lemma bc_Q : forall (fx : FPState) regs (m : word -> option byte) (s pixd datad wpld datat wplt hd : Z),
  (4096 + 272 <= s <= 2 ^ 47)%Z ->
  (4096 <= pixd)%Z ->
  (pixd + 64 <= s - 272)%Z ->
  (0 <= datad < 2 ^ 47)%Z ->
  (0 <= wpld <= 20000)%Z ->
  (0 <= datat < 2 ^ 47)%Z ->
  (0 <= wplt <= 20000)%Z ->
  (1 <= hd < 2 ^ 31)%Z ->
  rdn SEGS m (Z_to_bv 64 (pixd + 56)) 8 = Some (Z_to_le_bytes 8 datad) ->
  rdn SEGS m (Z_to_bv 64 (pixd + 16)) 4 = Some (Z_to_le_bytes 4 wpld) ->
  rdn SEGS m (Z_to_bv 64 (s - 200)) 8 = Some (Z_to_le_bytes 8 datat) ->
  rdn SEGS m (Z_to_bv 64 (s - 184)) 8 = Some (Z_to_le_bytes 8 11) ->
  rdn SEGS m (Z_to_bv 64 (s - 264)) 8 = Some (Z_to_le_bytes 8 (2 ^ 64 - 40)) ->
  store_ok SEGS m (Z_to_bv 64 (s - 272)) 272 = true ->
  getr regs 2 = Z_to_bv 64 (s - 272) ->
  getr regs 10 = Z_to_bv 64 pixd ->
  getr regs 27 = Z_to_bv 64 wplt ->
  getr regs 21 = Z_to_bv 64 hd ->
  reach SEGS (@mkst fx regs (Z_to_bv 64 187896) m rom)
    (fun fin => exists regs' M', fin = @mkst fx regs' (Z_to_bv 64 187984) M' rom /\
      rinv [((s - 208)%Z, 8%Z)] m M' /\ rdn SEGS M' (Z_to_bv 64 (s - 208)) 8 = Some (Z_to_le_bytes 8 pixd) /\
      getr regs' 1 = Z_to_bv 64 datat /\ getr regs' 2 = Z_to_bv 64 (s - 272) /\ getr regs' 8 = Z_to_bv 64 datad /\ getr regs' 10 = Z_to_bv 64 wpld /\
      getr regs' 11 = Z_to_bv 64 0 /\ getr regs' 12 = Z_to_bv 64 (4 * wplt) /\ getr regs' 31 = Z_to_bv 64 11 /\
      getr regs' 13 = Z_to_bv 64 (datat + 4 * wplt + 11) /\
      regs_agree (fun r => In r [1; 8; 10; 11; 12; 13; 14; 31]%list) regs regs').
