Lemma bc_S : forall (fx : FPState) regs (m : word -> option byte) (s pa pixd : Z),
  (4096 + 272 <= s <= 2 ^ 47)%Z ->
  (0 <= pa < 2 ^ 64)%Z ->
  (0 <= pixd < 2 ^ 64)%Z ->
  rdn SEGS m (Z_to_bv 64 (s - 224)) 8 = Some (Z_to_le_bytes 8 pa) ->
  rdn SEGS m (Z_to_bv 64 (s - 208)) 8 = Some (Z_to_le_bytes 8 pixd) ->
  getr regs 2 = Z_to_bv 64 (s - 272) ->
  reach SEGS (@mkst fx regs (Z_to_bv 64 187524) m rom)
    (fun fin => exists regs' M', fin = @mkst fx regs' (Z_to_bv 64 98836) M' rom /\
      M' = m /\ getr regs' 1 = Z_to_bv 64 187540 /\ getr regs' 2 = Z_to_bv 64 (s - 272) /\ getr regs' 10 = Z_to_bv 64 pa /\ getr regs' 11 = Z_to_bv 64 pixd /\
      getr regs' 12 = Z_to_bv 64 0 /\ regs_agree (fun r => In r [1; 10; 11; 12]%list) regs regs').
Proof.
