Lemma bc_T_last : forall (fx : FPState) regs (m : word -> option byte) (s bsc nc : Z),
  (4096 + 272 <= s <= 2 ^ 47)%Z ->
  (0 <= bsc < 2 ^ 64)%Z ->
  (0 <= nc < 2 ^ 64)%Z ->
  rdn SEGS m (Z_to_bv 64 (s - 192)) 8 = Some (Z_to_le_bytes 8 9) ->
  rdn SEGS m (Z_to_bv 64 (s - 216)) 8 = Some (Z_to_le_bytes 8 10) ->
  rdn SEGS m (Z_to_bv 64 (s - 232)) 8 = Some (Z_to_le_bytes 8 bsc) ->
  rdn SEGS m (Z_to_bv 64 (s - 240)) 8 = Some (Z_to_le_bytes 8 nc) ->
  getr regs 2 = Z_to_bv 64 (s - 272) ->
  reach SEGS (@mkst fx regs (Z_to_bv 64 187540) m rom)
    (fun fin => exists regs' M', fin = @mkst fx regs' (Z_to_bv 64 188220) M' rom /\
      M' = m /\ getr regs' 2 = Z_to_bv 64 (s - 272) /\ getr regs' 8 = Z_to_bv 64 (10) /\ getr regs' 11 = Z_to_bv 64 bsc /\ getr regs' 26 = Z_to_bv 64 nc /\
      regs_agree (fun r => In r [8; 10; 11; 26]%list) regs regs').
Proof.
