Lemma bc_U : forall (fx : FPState) regs (m : word -> option byte) (s bil pa : Z),
  (4096 + 272 <= s <= 2 ^ 47)%Z ->
  (4096 <= bil)%Z ->
  (bil + 104 <= s - 272)%Z ->
  (0 <= pa < 2 ^ 64)%Z ->
  rdn SEGS m (Z_to_bv 64 (s - 272)) 8 = Some (Z_to_le_bytes 8 bil) ->
  rdn SEGS m (Z_to_bv 64 (s - 224)) 8 = Some (Z_to_le_bytes 8 pa) ->
  store_ok SEGS m (Z_to_bv 64 bil) 104 = true ->
  getr regs 2 = Z_to_bv 64 (s - 272) ->
  reach SEGS (@mkst fx regs (Z_to_bv 64 188220) m rom)
    (fun fin => exists regs' M', fin = @mkst fx regs' (Z_to_bv 64 100856) M' rom /\
      rinv [((bil + 88)%Z, 8%Z)] m M' /\ rdn SEGS M' (Z_to_bv 64 (bil + 88)) 8 = Some (Z_to_le_bytes 8 pa) /\
      getr regs' 1 = Z_to_bv 64 188240 /\ getr regs' 2 = Z_to_bv 64 (s - 272) /\ getr regs' 8 = Z_to_bv 64 bil /\ getr regs' 10 = Z_to_bv 64 pa /\
